
using System.Diagnostics;
using System.Net.Http;
using System.Net.Http.Json;
using System.Net.Http.Headers;
using System.Text.Json;
using System.Windows.Forms;
namespace PeoYameTray;
internal static class Program {
 static Process? backend; static NotifyIcon? tray; static readonly HttpClient http=new();
 static string DataDir=>Environment.GetEnvironmentVariable("PEO_YAME_DATA_DIR")??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Peo Yame","data");
 static int Port=>int.TryParse(Environment.GetEnvironmentVariable("PORT"),out var p)?p:3000;
 [STAThread] static int Main(string[] args){var diagnostic=Environment.GetEnvironmentVariable("PEO_YAME_SELF_TEST_LOG");if(!string.IsNullOrEmpty(diagnostic))File.AppendAllText(diagnostic,"Main entered: "+string.Join(" ",args)+Environment.NewLine);if(args.Contains("--self-test")){try{return SelfTest().GetAwaiter().GetResult();}catch(Exception e){var log=Environment.GetEnvironmentVariable("PEO_YAME_SELF_TEST_LOG")??Path.Combine(Path.GetTempPath(),"PeoYame-self-test.log");File.WriteAllText(log,e.ToString());return 2;}}ApplicationConfiguration.Initialize();Directory.CreateDirectory(DataDir);
 var menu=new ContextMenuStrip();menu.Items.Add("Start",null,async(_,_)=>await StartAsync());menu.Items.Add("Restart backend",null,async(_,_)=>await RestartAsync());menu.Items.Add("Stop",null,(_,_)=>StopBackend());menu.Items.Add(new ToolStripSeparator());menu.Items.Add("Quit",null,(_,_)=>{StopBackend();tray!.Visible=false;Application.Exit();});
 var ico=Path.Combine(AppContext.BaseDirectory,"PeoYame.ico");tray=new NotifyIcon{Text="Peo Yame",Icon=File.Exists(ico)?new Icon(ico):System.Drawing.SystemIcons.Application,ContextMenuStrip=menu,Visible=true};tray.DoubleClick+=async(_,_)=>await StartAsync();Application.Run();return 0;}
 static async Task StartAsync(){await StartBackendAsync(false);try{Process.Start(new ProcessStartInfo($"http://127.0.0.1:{Port}"){UseShellExecute=true});}catch{}}
 static async Task RestartAsync(){StopBackend();await StartBackendAsync(true);try{Process.Start(new ProcessStartInfo($"http://127.0.0.1:{Port}"){UseShellExecute=true});}catch{}}
 static async Task StartBackendAsync(bool reset){if(backend is {HasExited:false})return;var root=Path.Combine(AppContext.BaseDirectory,"backend");var node=Path.Combine(root,"node.exe");if(!File.Exists(node))throw new FileNotFoundException("Backend runtime is missing.",node);var psi=new ProcessStartInfo(node,"src/server.js"){WorkingDirectory=root,UseShellExecute=false,CreateNoWindow=true};psi.Environment["PEO_YAME_DATA_DIR"]=DataDir;psi.Environment["PORT"]=Port.ToString();psi.Environment["PEO_YAME_DEMO_ENABLED"]="true";if(reset)psi.Environment["PEO_YAME_RESET_INSTANCE"]="true";psi.RedirectStandardOutput=true;psi.RedirectStandardError=true;backend=Process.Start(psi);if(Environment.GetEnvironmentVariable("PEO_YAME_SELF_TEST_LOG") is string log){backend!.OutputDataReceived+=(s,e)=>{if(e.Data!=null)File.AppendAllText(log,e.Data+Environment.NewLine);};backend.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)File.AppendAllText(log,e.Data+Environment.NewLine);};backend.BeginOutputReadLine();backend.BeginErrorReadLine();}for(var i=0;i<40;i++){try{using var r=await http.GetAsync($"http://127.0.0.1:{Port}/api/health");if(r.IsSuccessStatusCode)return;}catch{}await Task.Delay(500);}throw new Exception("Peo Yame backend did not become ready.");}
 static void StopBackend(){try{if(backend is {HasExited:false}){backend.Kill(true);backend.WaitForExit(5000);}}catch{}backend=null;}
 static async Task<int> SelfTest(){var temp=Path.Combine(Path.GetTempPath(),"peoyame-ci-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);var oldData=Environment.GetEnvironmentVariable("PEO_YAME_DATA_DIR");var oldPort=Environment.GetEnvironmentVariable("PORT");Environment.SetEnvironmentVariable("PEO_YAME_DATA_DIR",temp);Environment.SetEnvironmentVariable("PORT",Port.ToString());try{await StartBackendAsync(false);using var ok=await http.GetAsync("http://127.0.0.1:"+Port+"/api/health");if(!ok.IsSuccessStatusCode)throw new Exception("start/health failed");using var reg=await http.PostAsJsonAsync("http://127.0.0.1:"+Port+"/api/account/register",new{name="Lifecycle Farmer",phone="71234567",password="lifecycle-check-password"});if(!reg.IsSuccessStatusCode)throw new Exception("registration failed");using var regJson=JsonDocument.Parse(await reg.Content.ReadAsStringAsync());var token=regJson.RootElement.GetProperty("token").GetString()!;using var siteRequest=new HttpRequestMessage(HttpMethod.Post,"http://127.0.0.1:"+Port+"/api/sites");siteRequest.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);siteRequest.Content=JsonContent.Create(new{name="Lifecycle store",crop="Maize"});using var siteResponse=await http.SendAsync(siteRequest);if(!siteResponse.IsSuccessStatusCode)throw new Exception("site setup failed");StopBackend();await StartBackendAsync(true);using var restart=await http.GetAsync("http://127.0.0.1:"+Port+"/api/health");if(!restart.IsSuccessStatusCode)throw new Exception("restart failed");using var login=await http.PostAsJsonAsync("http://127.0.0.1:"+Port+"/api/account/login",new{phone="71234567",password="lifecycle-check-password"});if(!login.IsSuccessStatusCode)throw new Exception("restart did not preserve login account");using var loginJson=JsonDocument.Parse(await login.Content.ReadAsStringAsync());var newToken=loginJson.RootElement.GetProperty("token").GetString()!;using var sitesRequest=new HttpRequestMessage(HttpMethod.Get,"http://127.0.0.1:"+Port+"/api/sites");sitesRequest.Headers.Authorization=new AuthenticationHeaderValue("Bearer",newToken);using var sitesResponse=await http.SendAsync(sitesRequest);using var sitesJson=JsonDocument.Parse(await sitesResponse.Content.ReadAsStringAsync());if(sitesJson.RootElement.GetArrayLength()!=0)throw new Exception("restart did not reset instance locations");StopBackend();try{using var stopped=await http.GetAsync("http://127.0.0.1:"+Port+"/api/health");throw new Exception("stop left the server responding");}catch(HttpRequestException){}return 0;}catch(Exception e){var message=e.ToString();File.WriteAllText(Path.Combine(temp,"self-test.log"),message);if(Environment.GetEnvironmentVariable("PEO_YAME_SELF_TEST_LOG") is string log)File.AppendAllText(log,message+Environment.NewLine);StopBackend();return 1;}finally{Environment.SetEnvironmentVariable("PEO_YAME_DATA_DIR",oldData);Environment.SetEnvironmentVariable("PORT",oldPort);if(!File.Exists(Path.Combine(temp,"self-test.log"))){try{Directory.Delete(temp,true);}catch{}}}}
}